(()=>{document.getElementById('kinnect-boot')?.remove();const area=document.querySelector('.showcase');if(!area)return;const fit=()=>{const scale=Math.max(0,Math.min(1,(area.clientHeight-12)/499,(area.clientWidth-24)/238));area.style.setProperty('--phone-scale',scale);area.classList.toggle('phone-ready',scale>0);};fit();new ResizeObserver(fit).observe(area);window.visualViewport?.addEventListener('resize',fit);})();
